// Context: When multiple script files need to react to play/stop, pass a Broadcaster
// as the callback function instead of a plain function. The TransportHandler will
// call the Broadcaster with the isPlaying argument, which propagates to all listeners.
const var th = Engine.createTransportHandler();

const var transportBroadcaster = Engine.createBroadcaster({
    "id": "Transport State",
    "args": ["isPlaying"]
});

// A Broadcaster can be passed directly as the callback function. It receives
// the isPlaying argument and dispatches it to all its listeners. This is the
// standard pattern for propagating transport state across multiple script files.
th.setOnTransportChange(AsyncNotification, transportBroadcaster);

// Now any script file can listen to transport changes through the Broadcaster
const var PlayButton = Content.addButton("PlayButton", 0, 0);
PlayButton.set("saveInPreset", false);

transportBroadcaster.addListener(PlayButton, "sync play button to transport",
    function(isPlaying)
    {
        this.setValue(isPlaying);
    });

// Context: A drum machine needs its own play/stop controls (internal clock) but should
// follow the DAW when the user enables host sync. A toggle button switches between
// PreferInternal (default) and PreferExternal modes at runtime.
const var th = Engine.createTransportHandler();

// Default: internal clock takes priority
th.setSyncMode(th.PreferInternal);
th.stopInternalClockOnExternalStop(true);

const var HostSyncButton = Content.addButton("HostSync", 0, 0);
HostSyncButton.set("saveInPreset", false);

inline function onHostSync(component, value)
{
    if (value)
        th.setSyncMode(th.PreferExternal);
    else
        th.setSyncMode(th.PreferInternal);
}

HostSyncButton.setControlCallback(onHostSync);

// Context: A simpler alternative for plugins that do not need fallback behavior.
// ExternalOnly ignores internal clock entirely; InternalOnly ignores the DAW.
const var th = Engine.createTransportHandler();

const var ExternalButton = Content.addButton("External", 0, 0);

inline function onExternalToggle(component, value)
{
    if (value)
        th.setSyncMode(th.ExternalOnly);
    else
        th.setSyncMode(th.InternalOnly);
}

ExternalButton.setControlCallback(onExternalToggle);

// Context: A drum machine starts its sequencer when a specific MIDI note is received.
// Using Message.getTimestamp() ensures the clock starts at the exact sample position
// of the note event within the audio block, not at the block boundary.
const var th = Engine.createTransportHandler();
th.setSyncMode(th.PreferInternal);
th.setEnableGrid(true, 8); // 1/8 note grid

// In onNoteOn callback:
// Start clock at the note's sample position for tight timing
// th.startInternalClock(Message.getTimestamp());

// From a UI play button (no MIDI context, so timestamp 0 is fine):
// th.startInternalClock(0);

// Context: When loading a new preset while playback was active, the clock must be
// stopped before load and restarted after. sendGridSyncOnNextCallback() ensures the
// grid restarts cleanly instead of continuing from a stale position.
const var th = Engine.createTransportHandler();
th.setEnableGrid(true, 8);

// Before preset load: stop the clock
th.stopInternalClock(0);

// After preset load completes: resync and restart
th.sendGridSyncOnNextCallback();
th.startInternalClock(0);

// Context: When using PreferInternal mode with a host-sync option, enabling this
// setting ensures the internal clock stops cleanly when the DAW transport stops.
// Without it, stopping the DAW while host-synced leaves the internal clock in
// an ambiguous state.
const var th = Engine.createTransportHandler();

// Standard setup sequence for a plugin with internal transport + host sync
th.setEnableGrid(true, 8);                    // 1/8 note grid
th.setSyncMode(th.PreferInternal);            // Internal clock by default
th.stopInternalClockOnExternalStop(true);     // Clean stop when DAW stops

